      let html=(legacy?'<span class="pill">ประวัติ v1 · ส่วนแบ่งรายรับ</span>':'<span class="pill">'+esc(status)+'</span>')+'<h3>'+esc(s.therapist_name||s.therapist_id)+'</h3>'+row('สถานะ',status==='booked'?'เชื่อมงานแล้ว':esc(status))+row('รายรับที่ตรวจจริง',thb(received))+row('คืนเงินจริง',thb(refunded))+row('รับสุทธิจริง',thb(net));
