      if(s.settlement && s.corrections?.length){html+='<h3>รายการแก้ไขหลังอนุมัติ · ประวัติเดิมคงเดิม</h3>'+s.corrections.map(c=>row(c.type==='customer_refund'?'คืนเงินลูกค้า · ภาระ '+(labels[c.role]||c.role):'รับคืนจาก '+(labels[c.role]||c.role),thb(c.amount)+' · '+esc(c.recipient))) .join('')+(s.reconciliation_summary?row('คืนเงินจริงรวม',thb(s.reconciliation_summary.total_refunded))+row('รับสุทธิหลังแก้ไข',thb(s.reconciliation_summary.net_received))+row('กระทบยอด',s.reconciliation_summary.balanced?'สมดุล':'รอตรวจ'):'');}
      const canCorrect=!!s.settlement && ['closed','reconciling'].includes(status);
      if(canCorrect){const roles=Object.entries(labels).map(([id,label])=>({id,label}));const returns=Object.entries(s.reconciliation_summary?.return_due||{}).filter(([,amount])=>amount>0).map(([role,amount])=>form('corrections','<input type="hidden" name="type" value="payee_return"><input type="hidden" name="role" value="'+esc(role)+'"><p class="muted">'+esc(labels[role])+' · ค้างรับคืน '+thb(amount)+'</p>'+field('amount','จำนวนรับคืนจริง (บาท)','number','min="0.01" max="'+(amount/100).toFixed(2)+'" step="0.01"')+field('recipient','บัญชีผู้รับเงินคืนที่ตรวจแล้ว')+field('occurred_at','วันเวลารับคืน · เวลาไทย','datetime-local')+field('evidence_ref','หลักฐานรับคืน')+field('terms_ref','ข้อตกลง / อนุมัติอ้างอิง')+field('reason','เหตุผล')+check('approval_confirmed','Owner อนุมัติการแก้ไขแล้ว')+check('verification_confirmed','Owner ตรวจเงินจริงและหลักฐานแล้ว'),'บันทึกรับคืนจาก '+labels[role],s.id)).join('');html+='<details><summary>บันทึกการแก้ไขหลังจ่าย · ไม่เปลี่ยน settlement/payout เดิม</summary>'+form('corrections','<input type="hidden" name="type" value="customer_refund">'+select('role','ฝ่ายที่รับภาระคืนเงิน',roles)+field('amount','จำนวนคืนเงิน (บาท)','number','min="0.01" step="0.01"')+field('recipient','ผู้รับเงินจริงลูกค้า')+field('occurred_at','วันเวลาคืนเงิน · เวลาไทย','datetime-local')+field('evidence_ref','หลักฐานคืนเงิน')+field('terms_ref','ข้อตกลง / อนุมัติอ้างอิง')+field('reason','เหตุผล')+check('approval_confirmed','Owner อนุมัติการแก้ไขแล้ว')+check('verification_confirmed','Owner ตรวจเงินจริงและหลักฐานแล้ว'),'บันทึกคืนเงินลูกค้า',s.id)+returns+'</details>';}
      const reserves=(agreement.adjustments||[]).map((x,index)=>({x,index})).filter(v=>['fee','tax'].includes(v.x.kind)&&v.x.amount>0);
